using SchoolERP.Application.Features.SchoolCalendar;using SchoolERP.Domain.Entities;using SchoolERP.Domain.Enums;using SchoolERP.Domain.Exceptions;using SchoolERP.Domain.Interfaces;using Xunit;namespace SchoolERP.UnitTests;public sealed class SchoolCalendarEventTests{private static SchoolCalendarEvent Make(bool allDay=true,DateOnly? end=null,TimeOnly? start=null,TimeOnly? finish=null)=>SchoolCalendarEvent.Create(Guid.NewGuid(),Guid.NewGuid(),null,null,"Event"," event_1 ",SchoolCalendarEventType.SchoolEvent,new(2026,10,12),end??new(2026,10,12),allDay,start,finish,false,"#abcdef",null,null);[Fact]public void Create_normalizes_and_sets_scope(){var x=Make();Assert.Equal("EVENT_1",x.Code);Assert.Equal("#ABCDEF",x.ColorHex);Assert.Equal(SchoolCalendarEventStatus.Draft,x.Status);Assert.IsAssignableFrom<ITenantEntity>(x);Assert.Null(x.CampusId);Assert.Null(x.AcademicYearId);}[Fact]public void All_day_clears_times(){var x=Make(true,start:new(9,0),finish:new(10,0));Assert.Null(x.StartTime);Assert.Null(x.EndTime);}[Fact]public void Timed_event_must_be_single_day_with_ordered_times(){Assert.Throws<DomainException>(()=>Make(false,start:new(10,0),finish:new(9,0)));Assert.Throws<DomainException>(()=>Make(false,new(2026,10,13),new(9,0),new(10,0)));}[Fact]public void Invalid_date_range_is_rejected()=>Assert.Throws<DomainException>(()=>Make(end:new(2026,10,11)));[Fact]public void Lifecycle_and_archive_rules_work(){var x=Make();x.Publish(DateTime.UtcNow);x.Cancel(DateTime.UtcNow);x.Archive(DateTime.UtcNow);Assert.Throws<SchoolCalendarArchivedReadOnlyException>(()=>x.Publish(DateTime.UtcNow));}[Fact]public void Request_omits_tenant_and_school(){var p=typeof(CalendarEventRequest).GetProperties().Select(x=>x.Name);Assert.DoesNotContain("TenantId",p);Assert.DoesNotContain("SchoolId",p);Assert.DoesNotContain("Status",p);}}
